/// HeroIcons 2.2 enums expose native Outline and Solid artwork for every entry.
String _toSnakeCase(String value) => value
    .replaceAllMapped(RegExp(r'([a-z0-9])([A-Z])'),
        (m) => '${m[1]}_${m[2]}')
    .toLowerCase();

final Map<String, HeroIcons> kCompleteHeroCategoryIcons = {
  for (final icon in HeroIcons.values) _toSnakeCase(icon.name): icon,
};
